// 一次，已用重量 100 千克、剩余 0（恰好达到承重仍是合法装载，重复调用
// 不得额外扣减或新增清单记录）；两件货物查询都显示已装载并属于 C1。
func assertDupFinalStowage(t *testing.T, r *Registry) {
	t.Helper()
