// 起跑线后并发提交。delayA/delayB > 0 时对应写法在开闸后先等待该时长，
// 用于覆盖两种完成先后；两者均为 0 时是纯粹的同时提交。返回两份结果。
func runDupRound(t *testing.T, variantA, variantB dupOpsVariant, delayA, delayB time.Duration) (dupOutcome, dupOutcome) {
	t.Helper()
	r := newDuplicateLoadRegistry(t)

	start := make(chan struct{})
