// 编号、同一安排的两次提交同时到达，多轮覆盖两种完成先后与纯粹的锁竞争，
// 两次调用都必须成功并拿到同一份首次装载记录，实际装载只发生一次。
func TestConcurrentDuplicateAdjustSameContentCommitsOnce(t *testing.T) {
	variants := dupOpsVariants()

