	}{
		{"原始写法对原始写法", variants[0], variants[0]},
		{"原始写法对交换顺序", variants[0], variants[1]},
		{"原始写法对首尾空白", variants[0], variants[2]},
		{"交换顺序对首尾空白", variants[1], variants[2]},
